#include <bits/stdc++.h>
using namespace std;
int main(){
    int n,Q; cin>>n>>Q; vector<int> at(n),bt(n),rem(n),ct(n);
    for(int i=0;i<n;i++){cin>>at[i]>>bt[i]; rem[i]=bt[i];}
    vector<int> ord(n); iota(ord.begin(),ord.end(),0);
    stable_sort(ord.begin(),ord.end(),[&](int a,int b){return at[a]<at[b];});
    queue<int> q; int idx=0, done=0; long long t=0;
    auto admit=[&](){ while(idx<n && at[ord[idx]]<=t) q.push(ord[idx++]); };
    while(done<n){
        if(q.empty()){ if(t<at[ord[idx]]) t=at[ord[idx]]; admit(); }
        int p=q.front(); q.pop(); int run=min(Q,rem[p]); t+=run; rem[p]-=run;
        admit();                       // arrivals during this slice go first
        if(rem[p]>0) q.push(p); else { ct[p]=t; done++; }
    }
    double st=0,sw=0;
    for(int i=0;i<n;i++){ int tat=ct[i]-at[i], wt=tat-bt[i]; st+=tat; sw+=wt;
        printf("P%d CT=%d TAT=%d WT=%d\n",i+1,ct[i],tat,wt); }
    printf("avgTAT=%.2f avgWT=%.2f\n",st/n,sw/n);
}

