using namespace std;
int main(){
    int n,C; cin>>n>>C; vector<int>a(n); for(auto&x:a)cin>>x;
    vector<int> P(n+1,0); for(int i=0;i<n;i++) P[i+1]=P[i]+a[i];
    int OFF=n+C+2; vector<int> nxt(2*OFF+1, INT_MAX);
    vector<long long> f0(n+1,0), fC(n+1,0);
    auto first=[&](int vu,int vo,int&j,bool&u){int ju=nxt[vu+OFF],jo=nxt[vo+OFF]; u=ju<jo; j=min(ju,jo);};
    for(int i=n;i>=0;i--){
        int j; bool u;
        first(P[i]-1, P[i]+C+1, j, u);  f0[i]=(j==INT_MAX)?0:1+(u?f0[j]:fC[j]);
        first(P[i]-C-1, P[i]+1, j, u);  fC[i]=(j==INT_MAX)?0:1+(u?f0[j]:fC[j]);
        if(i>0) nxt[P[i]+OFF]=i;
    }
    int bestX=0; long long best=LLONG_MAX;
    for(int X=0;X<=C;X++){
        int j; bool u; first(-X-1, C-X+1, j, u);
        long long d=(j==INT_MAX)?0:1+(u?f0[j]:fC[j]);
        if(d<best){best=d;bestX=X;}
    }
    cout<<bestX<<"\n";
}

