#include <stack>
Node* sumList(Node* a, Node* b){
    std::stack<int> sa, sb;
    for(;a;a=a->next) sa.push(a->val);
    for(;b;b=b->next) sb.push(b->val);
    Node* res=nullptr; int c=0;
    while(!sa.empty()||!sb.empty()||c){
        int s=c;
        if(!sa.empty()){ s+=sa.top(); sa.pop(); }
        if(!sb.empty()){ s+=sb.top(); sb.pop(); }
        Node* n=new Node(s%10); n->next=res; res=n; c=s/10;
    }
    return res;
}

