Node* reverseBetween(Node* head,int L,int R){
    Node dummy(0); dummy.next=head; Node* pre=&dummy;
    for(int i=1;i<L;i++) pre=pre->next;
    Node* cur=pre->next;
    for(int i=0;i<R-L;i++){
        Node* t=cur->next; cur->next=t->next; t->next=pre->next; pre->next=t;
    }
    return dummy.next;
}

