Node* reverseK(Node* head,int k){
    Node* t=head; for(int i=0;i<k;i++){ if(!t) return head; t=t->next; }
    Node *prev=nullptr,*cur=head;
    for(int i=0;i<k;i++){ Node* nx=cur->next; cur->next=prev; prev=cur; cur=nx; }
    head->next = reverseK(cur,k);
    return prev;
}

