Node* sortList(Node* h){
    if(!h||!h->next) return h;
    Node *s=h,*f=h->next;
    while(f&&f->next){ s=s->next; f=f->next->next; }
    Node* mid=s->next; s->next=nullptr;
    return mergeL(sortList(h), sortList(mid));
}

