using namespace std; typedef long long ll; const ll MOD=1e9+7;
ll solve(ll N,ll X,int D){
    vector<ll> cur(8*D,0), nx(8*D); cur[7*D]=1;
    for(int bit=30;bit>=0;bit--){
        fill(nx.begin(),nx.end(),0); int nb=N>>bit&1, xb=X>>bit&1;
        for(int t=0;t<8;t++) for(int r=0;r<D;r++){ ll v=cur[t*D+r]; if(!v) continue;
            int tA=t>>2&1, tB=t>>1&1, tX=t&1;
            for(int a=0;a<2;a++) for(int b=0;b<2;b++){
                if((tA&&a>nb)||(tB&&b>nb)||(tX&&(a^b)>xb)) continue;
                int nt=((tA&&a==nb)<<2)|((tB&&b==nb)<<1)|(tX&&(a^b)==xb);
                ll &w=nx[nt*D+(2*r+a+b)%D]; w=(w+v)%MOD; } }
        swap(cur,nx);
    }
    ll tot=0; for(int t=0;t<8;t++) tot=(tot+cur[t*D])%MOD;
    ll z=min(N,X)/D+1;                       // pairs with A=0 (and symmetric B=0)
    return ((tot-2*z+1)%MOD+MOD)%MOD;
}
int main(){ ll N,X; int D; cin>>N>>X>>D; cout<<solve(N,X,D)<<"\n"; }

