using namespace std; typedef long long ll; typedef unsigned long long ull;
int minLcmSub(const vector<ll>& a){
    int n=a.size(); vector<map<ll,int>> fa(n); map<ll,int> mx;
    for(int i=0;i<n;i++){ ll x=a[i];
        for(ll p=2;p*p<=x;p++) while(x%p==0){ fa[i][p]++; x/=p; }
        if(x>1) fa[i][x]++;
        for(auto& [p,e]:fa[i]) mx[p]=max(mx[p],e); }
    vector<ll> ps; for(auto& [p,e]:mx) ps.push_back(p);
    int K=ps.size(); ull full=(K==64)?~0ULL:((1ULL<<K)-1);
    unordered_map<ull,int> dp; dp[0]=0;
    for(int i=0;i<n;i++){ ull m=0;
        for(int k=0;k<K;k++){ auto it=fa[i].find(ps[k]); if(it!=fa[i].end()&&it->second==mx[ps[k]]) m|=1ULL<<k; }
        if(!m) continue; auto cur=dp;
        for(auto& [s,c]:cur){ ull ns=s|m; auto it=dp.find(ns); if(it==dp.end()||it->second>c+1) dp[ns]=c+1; } }
    return max(1, dp[full]);
}

